INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What does Wickramarachchi Print & Packaging manufacture?', 'We provide customized printing and packaging solutions including corrugated boxes, custom printed boxes, lunch/food boxes, paper bags, cake packaging, courier bags, textile packaging bags, non-woven bags, zipper pouches, mailer boxes, BOPP/LDPE/HDPE printed bags, gift & rigid boxes, and PP/polyester cords.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Where are you located?', 'We are located at No. 444/3, Nedungahena, Weliweriya, Sri Lanka.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('How can I contact your sales team?', 'You can contact us on +94 33 22 57592 or +94 71 777 6010, or email saleswickpack@gmail.com.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you manufacture customized packaging?', 'Yes. Most of our packaging products can be customized according to your size, quantity, material, printing and finishing requirements.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you manufacture according to my existing sample?', 'Yes. Please send us clear photos and specifications or arrange to provide a physical sample. Our team will check production feasibility.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can I get a quotation?', 'Certainly. Please provide the product type, size, quantity, material/specification, printing colours, artwork and a sample/photo if available.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you manufacture corrugated boxes?', 'Yes. We manufacture customized corrugated cartons for different commercial and industrial applications.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you manufacture 3-ply and 5-ply boxes?', 'Yes. The suitable construction depends on the product weight, carton dimensions and required strength.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you make printed corrugated boxes?', 'Yes. Printing is available according to the required design and number of colours.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you make die-cut corrugated boxes?', 'Yes. Customized die-cut designs can be considered according to customer requirements.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you manufacture a carton based on my existing box?', 'Yes. Please provide a physical sample or clear photographs together with the dimensions.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What information is required for a quotation?', 'Please provide: Length × Width × Height Required quantity 3-ply/5-ply requirement, if known Product and approximate weight packed inside Printing requirement/number of colours Artwork or sample, if available.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('I don''t know whether I need 3-ply or 5-ply. What should I do?', 'No problem. Tell us the product, packed weight, carton size, stacking/storage conditions and transportation requirement. Our team can recommend a suitable specification.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you manufacture custom printed boxes?', 'Yes. We manufacture customized boxes according to your required size, design and quantity.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you offer offset printing?', 'Yes. Offset-printed packaging solutions are available depending on the job specification.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you offer digital printing?', 'Digital printing can be considered depending on the product, quantity and required finish.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you print my company logo?', 'Yes. Please send us your logo or artwork in the best available quality.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can I choose my own colours?', 'Yes. Please provide the required colour references/artwork. Final colour feasibility will be confirmed during artwork and production review.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What details are required for pricing?', 'Please provide box size, quantity, material requirement, printing colours, finishing requirements and artwork.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you manufacture lunch boxes and food boxes?', 'Yes. Customized food and takeaway packaging options are available.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you print our restaurant logo?', 'Yes. Please send your logo/artwork, box dimensions and required quantity.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you manufacture different sizes?', 'Yes. Please provide your required dimensions or a sample.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can I send you my existing food box as a sample?', 'Yes. A physical sample is useful for determining size, construction and material requirements.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What do you need for a quotation?', 'Please provide the box size, food/application, required quantity, printing requirement and sample/artwork if available.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you manufacture paper bags?', 'Yes. We provide customized paper bags for retail, corporate, promotional and other applications.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you print our logo on paper bags?', 'Yes.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you make different bag sizes?', 'Yes. Bags can be manufactured according to the required dimensions, subject to production feasibility.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you provide bags with handles?', 'Yes. Handle options can be discussed according to the bag specification.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can I choose the paper type?', 'Available paper options depend on your application and required finish. Our team can recommend a suitable material.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What information do you need?', 'Please provide width × height × gusset, quantity, paper preference if known, printing colours, handle requirement and artwork.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you manufacture cake boxes?', 'Yes. We manufacture cake packaging in different sizes and designs.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you manufacture cupcake boxes?', 'Yes. Please provide the number of cupcakes, required box dimensions and quantity.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you supply cake base boards?', 'Yes. Please provide the required dimensions, shape and quantity.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can my bakery logo be printed?', 'Yes. Please send us your artwork/logo for evaluation.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you make a special size?', 'Customized sizes can be considered. Please send your required dimensions or existing sample.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What details should a bakery provide for a quotation?', 'Please provide product type, dimensions, quantity, printing requirement, artwork and sample/photo if available.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you supply courier bags?', 'Yes. Courier/e-commerce packaging bags are available according to the required specification.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you print our company name/logo?', 'Yes. Customized printing can be considered.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you make different sizes?', 'Yes. Please provide the required width and length.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can I order plain bags?', 'Please provide your size and quantity and our team will confirm the available production option.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What information is required for a quotation?', 'Size, quantity, material/thickness if known, printing colours and artwork.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you manufacture bags for garments and textiles?', 'Yes. We provide customized packaging solutions for garment and textile products.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you print our clothing brand logo?', 'Yes.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you make different sizes for different garments?', 'Yes. Please provide the required dimensions and quantities for each size.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What material should I use?', 'The suitable material depends on the garment and required appearance/protection. Please tell us your application and our team will advise.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What details are required for pricing?', 'Size, material/thickness if known, quantity, printing colours and artwork.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you manufacture non-woven bags?', 'Yes. Customized non-woven shopping and promotional bags are available.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you print our logo?', 'Yes. Printing options depend on the artwork and bag specification.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you make custom sizes?', 'Yes, subject to production feasibility.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can I select the bag colour?', 'Please tell us your required colour and quantity. Our team will confirm material/colour availability.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What information is needed for a quotation?', 'Bag dimensions, quantity, material/GSM if known, bag colour, printing colours and artwork.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you supply zipper pouches?', 'Yes. We provide zipper/zip-lock pouch solutions depending on the required application.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can zipper pouches be printed?', 'Printed options can be evaluated according to the material, quantity and artwork.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can I use them for spices or food?', 'Please tell us the exact product, required shelf life, pack weight and storage conditions. Our team will recommend or confirm the appropriate packaging specification.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What sizes are available?', 'Please provide your required pack weight or pouch dimensions. Our team will confirm the suitable option.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What information is needed for a quotation?', 'Product being packed, pack weight, pouch dimensions, material/structure if known, quantity, printing requirement and artwork.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you manufacture mailer boxes?', 'Yes. Customized mailer boxes are available for e-commerce, gifts and product deliveries.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can mailer boxes be printed?', 'Yes.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can I customize the size?', 'Yes. Please provide the internal or required box dimensions and product details.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you manufacture according to my sample?', 'Yes. Please provide the sample for evaluation.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What information is required for a quotation?', 'Size, quantity, product packed inside, printing requirements and artwork/sample.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you manufacture printed plastic packaging bags?', 'Yes. We provide flexible packaging printing solutions including BOPP, LDPE and HDPE applications, subject to the required specification.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you print multiple colours?', 'Yes. Multi-colour flexographic printing is available. Please send your artwork for evaluation.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What information do you need?', 'Please provide: Product being packed Bag type Width × length Gusset, if applicable Material Micron/thickness Required quantity Number of printing colours Artwork.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('I don''t know which material to use. Can you recommend one?', 'Yes. Tell us what you are packing, pack weight, required shelf life and storage conditions. Our technical team can advise on an appropriate packaging option.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you print food packaging?', 'Please provide the product and required packaging specification. Our team will evaluate the material and printing requirements for the intended application.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you print rice packaging?', 'Please provide the rice pack weight, bag dimensions, material requirement, quantity and artwork.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you print fertilizer packaging?', 'Please provide the product, pack weight, required bag dimensions, material specification, quantity and artwork so our team can evaluate the requirement.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you manufacture gift boxes?', 'Yes. Customized gift packaging can be developed according to customer requirements.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you manufacture rigid boxes?', 'Yes. Please send your required dimensions, design/reference, quantity and finishing requirements.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can I print my brand/logo?', 'Yes.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you make premium packaging?', 'Please send your design/reference, desired finish and budget requirement. Our team can discuss suitable production options.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you manufacture based on a reference picture?', 'Yes. Please upload the picture together with the required size and quantity. Final feasibility will be confirmed after review.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you manufacture/supply cord?', 'Yes. PP and polyester cord options are available for packaging and bag-handle applications.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What cord sizes are available?', 'Please provide the required diameter, application and quantity. Our team will confirm the available manufacturing specification.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can I request a particular colour?', 'Yes. Please provide the required colour/sample. Colour matching and availability will be confirmed by our team.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can the cord be used for paper bag handles?', 'Yes. Cord can be produced for suitable paper-bag handle applications.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('How should I request a quotation?', 'Please provide cord material, diameter, colour, total quantity in metres/yards or kilograms, a nd intended application.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What printing methods do you provide?', 'Depending on the packaging product, we provide flexographic, offset, screen and other suitable p rinting solutions.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you print my logo?', 'Yes. Please send your original/high-resolution logo or artwork.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What artwork formats can I send?', 'Original/vector artwork such as AI, EPS or print-ready PDF is preferred where available. Other high-resolution files can also be sent for checking.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('I only have a JPG/photo. Can you use it?', 'Please send it to us. Our artwork team will check whether it is suitable or whether redrawing/preparation is required.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you exactly match a colour?', 'Please provide the required colour reference or approved physical sample. Our team will evaluate colour matching based on the printing process, material and ink.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do I approve the artwork before production?', 'Where artwork approval is required, our team will arrange the appropriate approval process before printing.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('How can I get a quotation?', 'Please select your required product and provide its dimensions, quantity, material, printing requirements and artwork/sample.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Why can''t the bot immediately give me a price?', 'Customized packaging prices depend on size, material, quantity, printing, finishing and other production r equirements. Our team must review these details to provide an accurate quotation.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Is the price lower for larger quantities?', 'Quantity is one of the factors affecting unit cost. Please provide your required quantity and our team will prepare the appropriate quotation.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('How long is a quotation valid?', 'Please refer to the validity period stated on the official quotation.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Does the quotation include delivery?', 'Please refer to the quotation. Delivery/courier charges may be quoted separately depending on the destination and order.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What is your minimum order quantity?', 'Minimum order quantities vary by product, dimensions, material and printing process. Please provide your requirement for confirmation.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can I order a small quantity?', 'Please provide the product, size and required quantity. Our team will check whether production is feasible.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can I order a sample first?', 'Sample availability and development depend on the product. Please send your requirement for confirmation.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('How do I place an order?', 'After receiving and accepting the quotation, our team will guide you through artwork/specification approval, payment requirements and order confirmation.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('How long does production take?', 'Production lead time varies depending on product, quantity, material availability, printing requirements and current production capacity. The applicable lead time will be confirmed for your order.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Has my order started production?', 'Please provide your customer/company name and PO/order number so our team can check.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('When will my order be completed?', 'Please provide your PO/order number. Our team will check the latest production status.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can I change my order after confirmation?', 'Please contact us immediately. Changes are subject to the current production stage, material commitments and feasibility.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Do you deliver islandwide?', 'Yes. We can arrange islandwide delivery for applicable orders.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Which courier service do you use?', 'Prompt Express is one of the courier services used for suitable deliveries.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('How long does courier delivery take?', 'The estimated delivery period is approximately 2–4 working days, depending on the destination and courier conditions.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Who pays the courier charge?', 'Courier charges are generally paid by the customer unless otherwise agreed.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What is the courier charge?', 'The current indicative Prompt Express rate provided to us is Rs.500 for the first 1 kg and Rs.140 for each additional 1 kg. Rates are subject to confirmation before dispatch.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What information do you need for delivery?', 'Please provide the recipient/company name, contact person''s name, complete delivery address, town/district and telephone number.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can I track my delivery?', 'Please provide your order/invoice number. Our team can assist with available dispatch/courier information.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('What payment methods do you accept?', 'The available payment method and terms will be stated in your quotation/invoice or confirmed by our accounts team.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can I pay by bank transfer?', 'Please request our approved company bank details from the authorized team before making payment.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can I get credit facilities?', 'Credit facilities are subject to company approval and applicable terms. Please discuss your requirement with our sales/accounts team.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can I get an invoice?', 'Yes. Official invoicing will be handled according to the confirmed order and company procedure.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Where should I send my payment slip?', 'Please send the payment confirmation through the approved company communication channel together with your company/customer name and invoice/order reference.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can I bring my existing packaging sample?', 'Yes. A physical sample is often the best way for us to understand your requirement.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you copy the dimensions of my existing package?', 'We can measure and evaluate your sample and develop an appropriate specification, subject to production feasibility.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you develop new packaging for my product?', 'Yes. Please tell us about your product, pack size/weight, required quantity, expected appearance and other important requirements.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Can you recommend the material?', 'Yes. Our team can recommend an appropriate option after understanding the product and packaging requirements.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('I have a problem with my order. What should I do?', 'We are sorry to hear that. Please provide your company/customer name, PO/invoice number, product description, affected quantity and clear photographs/videos of the issue.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('There is a printing problem. What should I do?', 'Please send clear photographs showing the issue together with the PO/invoice number and affected quantity. Our team will review it.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('The colour is different from the approved sample. What should I do?', 'Please send photographs of the supplied product and approved reference/sample details. Our quality team will investigate.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('Some items are damaged. What should I do?', 'Please keep the affected products and packaging available for inspection and send us photos, quantity affected and your order/invoice reference.', true);
INSERT INTO wickpack_customization.faqs (question, answer, is_active) VALUES ('How quickly will you resolve my complaint?', 'Our team will review the information and contact you after the necessary investigation. We will avoid giving an unconfirmed resolution time.', true);
